# Builds every model in catalog.json into site/public/models/<id>.usdz,
# plus a thumbnail in site/public/thumbs/<id>.png (see thumbs.py).
#
#   .venv/bin/python models/build.py [id ...]
#
# Wear models are generated by wear.py. Downloaded models (models/downloads/,
# not committed) get the fixes AR Quick Look needs: MaterialBindingAPI on
# every bound mesh, no broken constant shading inputs, and a real-world size,
# standing on the floor.
import json, os, shutil, sys, tempfile, zipfile
from pxr import Gf, Usd, UsdGeom, UsdShade, UsdUtils

import thumbs, wear

HERE = os.path.dirname(os.path.abspath(__file__))
SITE = os.path.join(HERE, "..", "site", "public")
CATALOG = json.load(open(os.path.join(HERE, "catalog.json")))

def fix_download(src, dst, size=None):
    # Unpack, so textures keep their paths next to the root layer.
    work = tempfile.mkdtemp()
    with zipfile.ZipFile(src) as z:
        z.extractall(work)
        root = next(n for n in z.namelist() if n.endswith((".usdc", ".usda", ".usd")))
    stage = Usd.Stage.Open(os.path.join(work, root))
    for prim in stage.Traverse():
        if prim.HasRelationship("material:binding") and not prim.HasAPI(UsdShade.MaterialBindingAPI):
            UsdShade.MaterialBindingAPI.Apply(prim)
        # RoomPlan writes constant occlusion 0 ("always in shadow") and a
        # constant normal (1, 1, 1), which isn't a direction. Unset, they
        # fall back to the defaults: no shadow, the mesh's own normals.
        if prim.GetTypeName() == "Shader":
            for name in ("occlusion", "normal"):
                attr = prim.GetAttribute(f"inputs:{name}")
                if attr and attr.HasAuthoredValue() and not UsdShade.Input(attr).HasConnectedSource():
                    prim.RemoveProperty(attr.GetName())
    # Stand it on the floor, centred, at the catalog's size (or its own).
    top = stage.GetDefaultPrim()
    box = UsdGeom.BBoxCache(stage.GetStartTimeCode(), ["default", "render"]).ComputeWorldBound(top).ComputeAlignedRange()
    scale = size / (max(box.GetSize()) * UsdGeom.GetStageMetersPerUnit(stage)) if size else 1.0
    mid = box.GetMidpoint()
    xf = UsdGeom.Xformable(top)
    ops = xf.GetOrderedXformOps()
    # Outermost first: the scaled model's bottom centre goes to the origin.
    move = xf.AddTranslateOp(UsdGeom.XformOp.PrecisionDouble, "fit")
    scl = xf.AddScaleOp(UsdGeom.XformOp.PrecisionDouble, "fit")
    move.Set(Gf.Vec3d(-mid[0] * scale, -box.GetMin()[1] * scale, -mid[2] * scale))
    scl.Set(Gf.Vec3d(scale))
    xf.SetXformOpOrder([move, scl] + ops)
    stage.GetRootLayer().Save()
    UsdUtils.CreateNewARKitUsdzPackage(stage.GetRootLayer().realPath, dst)
    shutil.rmtree(work)

def build(model):
    dst = os.path.join(SITE, "models", f"{model['id']}.usdz")
    if os.path.exists(dst):
        os.remove(dst)
    made = model["made"]
    if "wear" in made:
        src = os.path.join(tempfile.mkdtemp(), "model.usdc")
        wear.write(made["wear"], src)
        UsdUtils.CreateNewARKitUsdzPackage(src, dst)
    else:
        fix_download(os.path.join(HERE, "downloads", made["download"]), dst, made.get("size"))
    thumbs.render(model)
    print(f"{model['id']:16} {os.path.getsize(dst) // 1024:6} KB")

if __name__ == "__main__":
    os.makedirs(os.path.join(SITE, "models"), exist_ok=True)
    os.makedirs(os.path.join(SITE, "thumbs"), exist_ok=True)
    wanted = set(sys.argv[1:])
    for model in CATALOG:
        if not wanted or model["id"] in wanted:
            build(model)
